import Foundation

enum WeekParser {
    static func parse(_ input:String,maxWeek:Int=40)->Set<Int>{let text=input.replacingOccurrences(of:"，",with:",").replacingOccurrences(of:"；",with:",").replacingOccurrences(of:"－",with:"-").replacingOccurrences(of:"—",with:"-").replacingOccurrences(of:"第",with:"").replacingOccurrences(of:"周次",with:"周");var out=Set<Int>();for m in text.allMatches(#"(\d{1,2})(?:\s*[-~至到]\s*(\d{1,2}))?\s*(?:周)?\s*(?:[（(]?\s*([单双])\s*(?:周)?\s*[）)]?)?"#){guard m.count>=4,let a=Int(m[1])else{continue};let b=Int(m[2]) ?? a;let parity=m[3];for w in max(1,min(a,b))...min(maxWeek,max(a,b)){if parity=="单"&&w%2==0{continue};if parity=="双"&&w%2 != 0{continue};out.insert(w)}};return out}
    static func format(_ weeks:Set<Int>)->String{let values=weeks.sorted();guard var start=values.first else{return ""};var last=start;var parts:[String]=[];for v in values.dropFirst(){if v==last+1{last=v}else{parts.append(start==last ? "\(start)":"\(start)-\(last)");start=v;last=v}};parts.append(start==last ? "\(start)":"\(start)-\(last)");return parts.joined(separator:",")+"周"}
}
enum SectionParser { static func parse(_ input:String)->[Int]{let text=input.replacingOccurrences(of:"，",with:",").replacingOccurrences(of:"；",with:",").replacingOccurrences(of:"－",with:"-").replacingOccurrences(of:"—",with:"-").replacingOccurrences(of:"第",with:"").replacingOccurrences(of:"节次",with:"").replacingOccurrences(of:"节",with:"").replacingOccurrences(of:" ",with:"");var out=Set<Int>();for m in text.allMatches(#"(\d{1,2})(?:[-~至到](\d{1,2}))?"#){guard m.count>=3,let a=Int(m[1])else{continue};let b=Int(m[2]) ?? a;for v in min(a,b)...max(a,b) where (1...40).contains(v){out.insert(v)}};return out.sorted()} }
struct ParsedExamTime:Equatable{var date:Date;var start:Int;var end:Int}
enum ExamTimeParser { static func parse(_ value:String)->ParsedExamTime?{guard let d=value.firstMatch(#"(20\d{2})\s*[-/.年]\s*(\d{1,2})\s*[-/.月]\s*(\d{1,2})\s*(?:日)?"#),let t=value.firstMatch(#"([01]?\d|2[0-3])\s*[:：]\s*([0-5]\d)\s*[-~—–至到]\s*([01]?\d|2[0-3])\s*[:：]\s*([0-5]\d)"#),d.count>=4,t.count>=5,let y=Int(d[1]),let mo=Int(d[2]),let day=Int(d[3]),let h1=Int(t[1]),let m1=Int(t[2]),let h2=Int(t[3]),let m2=Int(t[4]),let date=LocalValue.calendar.date(from:DateComponents(year:y,month:mo,day:day))else{return nil};let start=h1*60+m1,end=h2*60+m2;return end>start ? ParsedExamTime(date:date,start:start,end:end):nil} }
